import redis.clients.jedis.Jedis;
import redis.clients.jedis.params.SetParams;
import java.util.UUID;
import java.util.concurrent.*;

public class RedisDistributedLock {
    private final Jedis jedis;
    private final String lockKey;
    private final String lockValue;
    private final long ttlMillis;
    private final ScheduledExecutorService scheduler;

    public RedisDistributedLock(Jedis jedis, String lockKey, long ttlMillis) {
        this.jedis = jedis;
        this.lockKey = lockKey;
        this.lockValue = UUID.randomUUID().toString();
        this.ttlMillis = ttlMillis;
        this.scheduler = Executors.newSingleThreadScheduledExecutor();
    }

    // 尝试获取锁
    public boolean tryLock(long waitTime, TimeUnit unit) throws InterruptedException {
        long deadline = System.currentTimeMillis() + unit.toMillis(waitTime);
        while (true) {
            // 原子加锁：SET key value NX PX ttl
            String result = jedis.set(lockKey, lockValue, SetParams.setParams().nx().px(ttlMillis));
            if ("OK".equals(result)) {
                startRenewal(); // 启动续期
                return true;
            }
            if (System.currentTimeMillis() > deadline) {
                return false;
            }
            Thread.sleep(100); // 退避重试
        }
    }

    // 释放锁：Lua 脚本保证原子性
    private static final String UNLOCK_SCRIPT = 
        "if redis.call('get', KEYS[1]) == ARGV[1] then " +
        "  return redis.call('del', KEYS[1]) " +
        "else " +
        "  return 0 " +
        "end";

    public boolean unlock() {
        stopRenewal();
        // 执行 Lua 脚本
        Long result = (Long) jedis.eval(UNLOCK_SCRIPT, 
            Collections.singletonList(lockKey), 
            Collections.singletonList(lockValue));
        return result != null && result == 1L;
    }

    // 启动续期（每 ttl/3 续期一次）
    private ScheduledFuture<?> renewalTask;
    private void startRenewal() {
        long renewalInterval = ttlMillis / 3;
        renewalTask = scheduler.scheduleAtFixedRate(() -> {
            try {
                // 续期：只有 value 匹配时才续期
                String script = 
                    "if redis.call('get', KEYS[1]) == ARGV[1] then " +
                    "  return redis.call('pexpire', KEYS[1], ARGV[2]) " +
                    "else " +
                    "  return 0 " +
                    "end";
                Long result = (Long) jedis.eval(script,
                    Collections.singletonList(lockKey),
                    java.util.Arrays.asList(lockValue, String.valueOf(ttlMillis)));
                if (result == null || result == 0L) {
                    // 锁已丢失，停止续期
                    stopRenewal();
                }
            } catch (Exception e) {
                // 续期失败，停止业务（此处简化处理）
                stopRenewal();
            }
        }, renewalInterval, renewalInterval, TimeUnit.MILLISECONDS);
    }

    private void stopRenewal() {
        if (renewalTask != null) {
            renewalTask.cancel(false);
        }
    }
}
